#include <memory>
#include <iostream>

int main() {
    std::auto_ptr<int> p1(new int(42));

    // Ownership transfer (p1 becomes null)
    std::auto_ptr<int> p2 = p1; 

    if (p1.get() == nullptr) {
        std::cout << "p1 is null after copy.\n";
    }

    // Accessing p2 is safe, accessing p1 is UB if dereferenced
    std::cout << "p2 value: " << *p2 << "\n";
}
